CREATE VIEW public.provider_full_view AS
 SELECT p.id,
    p.npi,
    p.last_name,
    p.first_name,
    p.middle_initial,
    p.credentials,
    p.entity_code,
    p.cms_street1,
    p.cms_street2,
    p.cms_city,
    p.cms_state,
    p.cms_zip,
    p.cms_country,
    p.specialty_code,
    p.specialty_desc,
    p.specialty_source,
    p.ruca_code,
    p.ruca_category,
    p.ruca_desc,
    p.hcpcs_code,
    p.hcpcs_desc,
    p.rbcs_level,
    p.rbcs_id,
    p.rbcs_desc,
    p.supplier_rental_ind,
    p.total_suppliers,
    p.total_claims,
    p.total_services,
    p.total_beneficiaries,
    p.avg_submitted_charge,
    p.avg_medicare_allowed,
    p.avg_medicare_payment,
    p.avg_medicare_standardized,
    p.created_at,
    p.updated_at,
    e.patient_focus,
    e.search_status,
    e.search_date,
    ( SELECT count(*) AS count
           FROM public.clinics c
          WHERE ((c.npi)::text = (p.npi)::text)) AS clinic_count
   FROM (public.providers p
     LEFT JOIN public.provider_enrichment e ON (((p.npi)::text = (e.npi)::text)));


